/// Raven `InitMoverTrData`.
///
/// "pos1", "pos2", and "speed" should be set before calling, so the
/// movement delta can be calculated.
/// Source: `oracle/oracle/codemp/game/g_mover.c:913-934`
pub fn InitMoverTrData(
    ent: *mut gentity_t,
) {
    unsafe {
        (*ent).s.pos.tr_type = trType_t::TR_STATIONARY;
        (*ent).s.pos.tr_base = (*ent).pos1;

        // calculate time to reach second position from speed
        let pos1 = (*ent).pos1;
        let pos2 = (*ent).pos2;
        let r#move = [pos2[0] - pos1[0], pos2[1] - pos1[1], pos2[2] - pos1[2]];
        let distance =
            (r#move[0] * r#move[0] + r#move[1] * r#move[1] + r#move[2] * r#move[2]).sqrt();
        if (*ent).speed == 0.0 {
            (*ent).speed = 100.0;
        }
        let speed = (*ent).speed;
        (*ent).s.pos.tr_delta = [r#move[0] * speed, r#move[1] * speed, r#move[2] * speed];
        (*ent).s.pos.tr_duration = (distance * 1000.0 / speed) as c_int;
        if (*ent).s.pos.tr_duration <= 0 {
            (*ent).s.pos.tr_duration = 1;
        }
    }
}

