/// Raven `G_MiscModelExplosion`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:2363-2377`
pub fn G_MiscModelExplosion(
    mins: vec3_t,
    maxs: vec3_t,
    size: c_int,
    chunkType: material_t,
) {
    unsafe {
        let mid = [
            (mins[0] + maxs[0]) * 0.5,
            (mins[1] + maxs[1]) * 0.5,
            (mins[2] + maxs[2]) * 0.5,
        ];

        let te = G_TempEntity(mid, entity_event_t::EV_MISC_MODEL_EXP as c_int);

        (*te).s.origin2 = maxs;
        (*te).s.angles2 = mins;
        (*te).s.time = size;
        (*te).s.eventParm = chunkType;
    }
}

/// Raven `G_Chunks`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:2379-2395`
pub fn G_Chunks(
    owner: c_int,
    origin: vec3_t,
    normal: vec3_t,
    mins: vec3_t,
    maxs: vec3_t,
    speed: f32,
    numChunks: c_int,
    chunkType: material_t,
    customChunk: c_int,
    baseScale: f32,
) {
    unsafe {
        let te = G_TempEntity(origin, entity_event_t::EV_DEBRIS as c_int);

        // Now it's time to cram everything horribly into the entitystate of
        // an event entity.
        (*te).s.owner = owner;
        (*te).s.origin = origin;
        (*te).s.angles = normal;
        (*te).s.origin2 = maxs;
        (*te).s.angles2 = mins;
        (*te).s.speed = speed;
        (*te).s.eventParm = numChunks;
        (*te).s.trickedentindex = chunkType;
        (*te).s.modelindex = customChunk;
        (*te).s.apos.tr_base[0] = baseScale;
    }
}

