/// Raven `GlassUse`.
///
/// Source: `oracle/oracle/codemp/game/g_mover.c:2930-2948`
pub fn GlassUse(
    self_: *mut gentity_t,
    other: *mut gentity_t,
    activator: *mut gentity_t,
) {
    unsafe {
        // no direct object to blame for the break, so fill the values with
        // whatever
        let mut temp1 = [
            ((*self_).r.mins[0] + (*self_).r.maxs[0]) * 0.5,
            ((*self_).r.mins[1] + (*self_).r.maxs[1]) * 0.5,
            ((*self_).r.mins[2] + (*self_).r.maxs[2]) * 0.5,
        ];

        let temp2 = [
            ((*other).r.mins[0] + (*other).r.maxs[0]) * 0.5,
            ((*other).r.mins[1] + (*other).r.maxs[1]) * 0.5,
            ((*other).r.mins[2] + (*other).r.maxs[2]) * 0.5,
        ];

        (*self_).pos2 = [temp1[0] - temp2[0], temp1[1] - temp2[1], temp1[2] - temp2[2]];
        (*self_).pos1 = temp1;

        let len = ((*self_).pos2[0] * (*self_).pos2[0]
            + (*self_).pos2[1] * (*self_).pos2[1]
            + (*self_).pos2[2] * (*self_).pos2[2])
            .sqrt();
        (*self_).pos2 = [
            (*self_).pos2[0] / len * 390.0,
            (*self_).pos2[1] / len * 390.0,
            (*self_).pos2[2] / len * 390.0,
        ];

        GlassDie(self_, other, activator, 100, meansOfDeath_t::MOD_UNKNOWN as c_int);
    }
}

